12	/// This trait provides a fallback function that delegates all calls to another
13	/// contract using the Stylus [`delegate_call`][delegate_call] function. We
14	/// refer to the second contract as the _implementation_ behind the proxy, and
15	/// it has to be specified by overriding the virtual [`IProxy::implementation`]
16	/// function.
17	///
18	/// Additionally, delegation to the implementation can be triggered manually
19	/// through the [`IProxy::do_fallback`] function, or to a different contract
20	/// through the [`IProxy::delegate`] function.
21	///
22	/// The success and return data of the delegated call will be returned back
23	/// to the caller of the proxy.
24	///
25	/// # Safety
26	///
27	/// This trait is unsafe to implement because it uses the `unsafe`
28	/// [`delegate_call`][delegate_call] function.
29	///
30	/// The caller must ensure that `self` is a valid contract storage context.
31	///
32	/// The caller must ensure that the implementation contract is a valid contract
33	/// address.
34	///
35	/// [delegate_call]: stylus_sdk::call::delegate_call
36	pub unsafe trait IProxy: TopLevelStorage + Sized {
37	    /// Delegates the current call to [`IProxy::implementation`].
38	    ///
39	    /// This function does not return to its internal call site, it will
40	    /// return directly to the external caller.
41	    ///
42	    /// # Arguments
43	    ///
44	    /// * `&mut self` - Write access to the contract's state.
45	    /// * `implementation` - The address of the implementation contract.
46	    /// * `calldata` - The calldata to delegate to the implementation contract.
47	    ///
48	    /// # Errors
49	    ///
50	    /// Returns a [`stylus_sdk::stylus_core::calls::errors::Error`] if the delegate call fails. This
51	    /// error may represent:
52	    /// * A revert from the implementation contract, containing the revert data.
53	    /// * Failure to decode the return data from the implementation contract.
54	    /// * Other low-level call failures as defined by the Stylus SDK.
55	    #[allow(clippy::missing_safety_doc)]
56	    unsafe fn delegate(
57	        &mut self,
58	        implementation: Address,
59	        calldata: &[u8],
60	    ) -> Result<Vec<u8>, Error> {
61	        call::delegate_call(Call::new_in(self), implementation, calldata)
62	    }
63	
64	    /// This is a virtual function that should be overridden so it
65	    /// returns the address to which the fallback function and
66	    /// [`IProxy::do_fallback`] should delegate.
67	    ///
68	    /// # Arguments
69	    ///
70	    /// * `&self` - Read access to the contract's state.
71	    ///
72	    /// # Errors
73	    ///
74	    /// Implementing contracts should define their own error types for this
75	    /// function. Typically, errors may include:
76	    /// * The implementation address is invalid (e.g., not a contract).
77	    /// * The implementation is not a contract.
78	    ///
79	    /// The error should be encoded as a `Vec<u8>`.
80	    fn implementation(&self) -> Result<Address, Vec<u8>>;
81	
82	    /// Fallback function that delegates calls to the address returned
83	    /// by [`IProxy::implementation`]. Will run if no other function in the
84	    /// contract matches the call data.
85	    ///
86	    /// # Arguments
87	    ///
88	    /// * `&mut self` - Write access to the contract's state.
89	    /// * `calldata` - The calldata to delegate to the implementation contract.
90	    ///
91	    /// # Errors
92	    ///
93	    /// Implementing contracts should define their own error types for this
94	    /// function. Typically, errors may include:
95	    /// * The implementation address is invalid (e.g., not a contract).
96	    /// * The implementation is not a contract.
97	    /// * The implementation reverted with a reason.
98	    ///
99	    /// The error should be encoded as a `Vec<u8>`.
100	    #[allow(clippy::missing_safety_doc)]
101	    unsafe fn do_fallback(
102	        &mut self,
103	        calldata: &[u8],
104	    ) -> Result<Vec<u8>, Vec<u8>> {
105	        Ok(self.delegate(self.implementation()?, calldata)?)
106	    }
107	}
