119	    #[entrypoint]
120	    #[storage]
121	    struct ProxyExample {
122	        implementation: StorageAddress,
123	        error_on_implementation: StorageBool}
124	
125	    #[public]
126	    impl ProxyExample {
127	        #[constructor]
128	        fn constructor(&mut self, implementation: Address) {
129	            self.implementation.set(implementation);
130	        }
131	
132	        fn set_error_on_implementation(
133	            &mut self,
134	            error_on_implementation: bool,
135	        ) {
136	            self.error_on_implementation.set(error_on_implementation);
137	        }
138	
139	        fn implementation(&self) -> Result<Address, Vec<u8>> {
140	            if self.error_on_implementation.get() {
141	                return Err("implementation error".abi_encode());
142	            }
143	            Ok(self.implementation.get())
144	        }
145	
146	        #[fallback]
147	        fn fallback(&mut self, calldata: &[u8]) -> ArbResult {
148	            unsafe { self.do_fallback(calldata) }
149	        }
150	    }
151	
152	    unsafe impl IProxy for ProxyExample {
153	        fn implementation(&self) -> Result<Address, Vec<u8>> {
154	            Self::implementation(self)
155	        }
156	    }
