242	    #[motsu::test]
243	    fn delegate(
244	        proxy: Contract<ProxyExample>,
245	        erc20: Contract<Erc20Example>,
246	        alice: Address,
247	        bob: Address,
248	    ) {
249	        proxy.sender(alice).constructor(erc20.address());
250	
251	        // verify initial balance is [`U256::ZERO`].
252	        let balance_of_alice_call =
253	            IERC20::balanceOfCall { account: alice }.abi_encode();
254	        let balance = proxy
255	            .sender(alice)
256	            .fallback(&balance_of_alice_call)
257	            .expect("should be able to get balance");
258	        assert_eq!(balance, U256::ZERO.abi_encode());
259	
260	        let total_supply_call = IERC20::totalSupplyCall {}.abi_encode();
261	        let total_supply = proxy
262	            .sender(alice)
263	            .fallback(&total_supply_call)
264	            .expect("should be able to get total supply");
265	        assert_eq!(total_supply, U256::ZERO.abi_encode());
266	
267	        // mint 1000 tokens.
268	        let amount = U256::from(1000);
269	
270	        let mint_call =
271	            IERC20::mintCall { to: alice, value: amount }.abi_encode();
272	        proxy
273	            .sender(alice)
274	            .fallback(&mint_call)
275	            .expect("should be able to mint");
276	        // TODO: this should assert that the transfer event was emitted on the
277	        // proxy
278	        // https://github.com/OpenZeppelin/stylus-test-helpers/issues/111
279	        erc20.assert_emitted(&erc20::Transfer {
280	            from: Address::ZERO,
281	            to: alice,
282	            value: amount});
283	
284	        // check that the balance can be accurately fetched through the proxy.
285	        let balance = proxy
286	            .sender(alice)
287	            .fallback(&balance_of_alice_call)
288	            .expect("should be able to get balance");
289	        assert_eq!(balance, amount.abi_encode());
290	
291	        let total_supply = proxy
292	            .sender(alice)
293	            .fallback(&total_supply_call)
294	            .expect("should be able to get total supply");
295	        assert_eq!(total_supply, amount.abi_encode());
296	
297	        // check that the balance can be transferred through the proxy.
298	        let transfer_call =
299	            IERC20::transferCall { to: bob, value: amount }.abi_encode();
300	        proxy
301	            .sender(alice)
302	            .fallback(&transfer_call)
303	            .expect("should be able to transfer");
304	
305	        // TODO: this should assert that the transfer event was emitted on the
306	        // proxy
307	        // https://github.com/OpenZeppelin/stylus-test-helpers/issues/111
308	        erc20.assert_emitted(&erc20::Transfer {
309	            from: alice,
310	            to: bob,
311	            value: amount});
312	
313	        let balance = proxy
314	            .sender(alice)
315	            .fallback(&balance_of_alice_call)
316	            .expect("should be able to get balance");
317	        assert_eq!(balance, U256::ZERO.abi_encode());
318	
319	        let balance_of_bob_call =
320	            IERC20::balanceOfCall { account: bob }.abi_encode();
321	        let balance = proxy
322	            .sender(alice)
323	            .fallback(&balance_of_bob_call)
324	            .expect("should be able to get balance");
325	        assert_eq!(balance, amount.abi_encode());
326	
327	        let total_supply = proxy
328	            .sender(alice)
329	            .fallback(&total_supply_call)
330	            .expect("should be able to get total supply");
331	        assert_eq!(total_supply, amount.abi_encode());
332	    }
