334	    #[motsu::test]
335	    fn delegate_returns_error(
336	        proxy: Contract<ProxyExample>,
337	        erc20: Contract<Erc20Example>,
338	        alice: Address,
339	        bob: Address,
340	    ) {
341	        proxy.sender(alice).constructor(erc20.address());
342	
343	        let amount = U256::from(1000);
344	        let transfer_call =
345	            IERC20::transferCall { to: bob, value: amount }.abi_encode();
346	        let err = proxy
347	            .sender(alice)
348	            .fallback(&transfer_call)
349	            .expect_err("should revert on transfer");
350	
351	        assert_eq!(
352	            err,
353	            erc20::ERC20InsufficientBalance {
354	                sender: alice,
355	                balance: U256::ZERO,
356	                needed: amount}
357	            .abi_encode()
358	        );
359	    }
