361	    #[motsu::test]
362	    fn direct_delegate_to_different_implementation(
363	        proxy: Contract<ProxyExample>,
364	        erc20: Contract<Erc20Example>,
365	        erc20_2: Contract<Erc20Example>,
366	        alice: Address,
367	    ) {
368	        proxy.sender(alice).constructor(erc20.address());
369	
370	        // mint tokens to the second contract.
371	        let amount = U256::from(500);
372	        erc20_2
373	            .sender(alice)
374	            .mint(alice, amount)
375	            .expect("should be able to mint");
376	
377	        // use direct delegate to call the second contract.
378	        let balance_of_call =
379	            IERC20::balanceOfCall { account: alice }.abi_encode();
380	        let balance = unsafe {
381	            proxy
382	                .sender(alice)
383	                .delegate(erc20_2.address(), &balance_of_call)
384	                .expect(
385	                    "should be able to delegate to different implementation",
386	                )
387	        };
388	        assert_eq!(balance, amount.abi_encode());
389	    }
390	
391	    #[motsu::test]
392	    fn fallback_reverts_on_implementation_error(
393	        proxy: Contract<ProxyExample>,
394	        alice: Address,
395	    ) {
396	        // create proxy with [`Address::ZERO`] as implementation (invalid).
397	        proxy.sender(alice).set_error_on_implementation(true);
398	
399	        let balance_of_call =
400	            IERC20::balanceOfCall { account: alice }.abi_encode();
401	        let err =
402	            proxy.sender(alice).fallback(&balance_of_call).motsu_expect_err(
403	                "should fail when implementation is zero address",
404	            );
405	
406	        assert_eq!(err, "implementation error".abi_encode());
407	    }
408	}
