30	/// State of an [`BeaconProxy`] contract.
31	#[storage]
32	pub struct BeaconProxy {
33	    beacon: StorageAddress}
34	
35	/// NOTE: Implementation of [`TopLevelStorage`] to be able use `&mut self` when
36	/// calling other contracts and not `&mut (impl TopLevelStorage +
37	/// BorrowMut<Self>)`. Should be fixed in the future by the Stylus team.
38	unsafe impl TopLevelStorage for BeaconProxy {}
