40	impl BeaconProxy {
41	    /// Initializes the proxy with `beacon`.
42	    ///
43	    /// If `data` is nonempty, it's used as data in a delegate call to the
44	    /// implementation returned by the beacon. This will typically be an
45	    /// encoded function call, and allows initializing the storage of the proxy
46	    /// like a Solidity constructor.
47	    ///
48	    /// # Arguments
49	    ///
50	    /// * `&mut self` - Write access to the contract's state.
51	    /// * `beacon` - The beacon address.
52	    /// * `data` - The data to pass to the beacon.
53	    ///
54	    /// # Errors
55	    ///
56	    /// * [`Error::InvalidBeacon`] - If the beacon is not a contract with the
57	    ///   interface [`IBeacon`][IBeacon].
58	    /// * [`Error::NonPayable`] - If the data is empty and
59	    ///   [`msg::value`][msg_value] is not [`U256::ZERO`][U256].
60	    ///
61	    /// [msg_value]: stylus_sdk::msg::value
62	    /// [IBeacon]: super::IBeacon
63	    /// [U256]: alloy_primitives::U256
64	    pub fn constructor(
65	        &mut self,
66	        beacon: Address,
67	        data: &Bytes,
68	    ) -> Result<(), Error> {
69	        Erc1967Utils::upgrade_beacon_to_and_call(self, beacon, data)?;
70	        self.beacon.set(beacon);
71	        Ok(())
72	    }
