74	    /// Returns the beacon.
75	    ///
76	    /// # Arguments
77	    ///
78	    /// * `&self` - Read access to the contract's state.
79	    #[must_use]
80	    pub fn get_beacon(&self) -> Address {
81	        self.beacon.get()
82	    }
83	}
