1	//! This contract implements a proxy that gets the implementation address for
2	//! each call from an [`UpgradeableBeacon`][UpgradeableBeacon].
3	//!
4	//! The beacon address can only be set once during construction, and cannot be
5	//! changed afterwards. It is stored in an immutable variable to avoid
6	//! unnecessary storage reads, and also in the beacon storage slot specified by
7	//! [ERC-1967] so that it can be accessed externally.
8	//!
9	//! CAUTION: Since the beacon address can never be changed, you must ensure that
10	//! you either control the beacon, or trust the beacon to not upgrade the
11	//! implementation maliciously.
12	//!
13	//! IMPORTANT: Do not use the implementation logic to modify the beacon storage
14	//! slot. Doing so would leave the proxy in an inconsistent state where the
15	//! beacon storage slot does not match the beacon address.
16	//!
17	//! [UpgradeableBeacon]: super::UpgradeableBeacon
18	//! [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
19	
20	use alloc::{vec, vec::Vec};
21	
22	use alloy_primitives::Address;
23	use stylus_sdk::{abi::Bytes, prelude::*, storage::StorageAddress};
24	
25	use crate::proxy::{
26	    beacon::IBeaconInterface,
27	    erc1967::{Erc1967Utils, Error},
28	    IProxy};
29	
30	/// State of an [`BeaconProxy`] contract.
31	#[storage]
32	pub struct BeaconProxy {
33	    beacon: StorageAddress}
34	
35	/// NOTE: Implementation of [`TopLevelStorage`] to be able use `&mut self` when
36	/// calling other contracts and not `&mut (impl TopLevelStorage +
37	/// BorrowMut<Self>)`. Should be fixed in the future by the Stylus team.
38	unsafe impl TopLevelStorage for BeaconProxy {}
39	
40	impl BeaconProxy {
41	    /// Initializes the proxy with `beacon`.
42	    ///
43	    /// If `data` is nonempty, it's used as data in a delegate call to the
44	    /// implementation returned by the beacon. This will typically be an
45	    /// encoded function call, and allows initializing the storage of the proxy
46	    /// like a Solidity constructor.
47	    ///
48	    /// # Arguments
49	    ///
50	    /// * `&mut self` - Write access to the contract's state.
51	    /// * `beacon` - The beacon address.
52	    /// * `data` - The data to pass to the beacon.
53	    ///
54	    /// # Errors
55	    ///
56	    /// * [`Error::InvalidBeacon`] - If the beacon is not a contract with the
57	    ///   interface [`IBeacon`][IBeacon].
58	    /// * [`Error::NonPayable`] - If the data is empty and
59	    ///   [`msg::value`][msg_value] is not [`U256::ZERO`][U256].
60	    ///
61	    /// [msg_value]: stylus_sdk::msg::value
62	    /// [IBeacon]: super::IBeacon
63	    /// [U256]: alloy_primitives::U256
64	    pub fn constructor(
65	        &mut self,
66	        beacon: Address,
67	        data: &Bytes,
68	    ) -> Result<(), Error> {
69	        Erc1967Utils::upgrade_beacon_to_and_call(self, beacon, data)?;
70	        self.beacon.set(beacon);
71	        Ok(())
72	    }
73	
74	    /// Returns the beacon.
75	    ///
76	    /// # Arguments
77	    ///
78	    /// * `&self` - Read access to the contract's state.
79	    #[must_use]
80	    pub fn get_beacon(&self) -> Address {
81	        self.beacon.get()
82	    }
83	}
84	
85	unsafe impl IProxy for BeaconProxy {
86	    fn implementation(&self) -> Result<Address, Vec<u8>> {
87	        Ok(IBeaconInterface::new(self.get_beacon()).implementation(self)?)
88	    }
89	}
