411	            .fallback(&transfer_call)
412	            .expect_err("should revert on transfer");
413	
414	        assert_eq!(
415	            err,
416	            erc20::ERC20InsufficientBalance {
417	                sender: alice,
418	                balance: U256::ZERO,
419	                needed: amount}
420	            .abi_encode()
421	        );
422	    }
423	}
