54	/// An [`Erc1967Utils`] error.
55	#[derive(SolidityError, Debug)]
56	pub enum Error {
57	    /// Indicates an error related to the fact that the `implementation`
58	    /// of the proxy is invalid.
59	    InvalidImplementation(ERC1967InvalidImplementation),
60	    /// Indicates an error related to the fact that the `admin` of the
61	    /// proxy is invalid.
62	    InvalidAdmin(ERC1967InvalidAdmin),
63	    /// Indicates an error related to the fact that the `beacon`
64	    /// of the proxy is invalid.
65	    InvalidBeacon(ERC1967InvalidBeacon),
66	    /// Indicates an error relatoed to the fact that an upgrade function
67	    /// sees [`stylus_sdk::self.vm().msg_value()`] > [`alloy_primitives::U256::ZERO`]
68	    /// that may be lost.
69	    NonPayable(ERC1967NonPayable),
70	    /// There's no code at `target` (it is not a contract).
71	    EmptyCode(address::AddressEmptyCode),
72	    /// A call to an address target failed. The target may have reverted.
73	    FailedCall(address::FailedCall),
74	    /// Indicates an error related to the fact that the delegate call
75	    /// failed.
76	    FailedCallWithReason(address::FailedCallWithReason)}
77	
78	impl From<address::Error> for Error {
79	    fn from(e: address::Error) -> Self {
80	        match e {
81	            address::Error::EmptyCode(e) => Error::EmptyCode(e),
82	            address::Error::FailedCall(e) => Error::FailedCall(e),
83	            address::Error::FailedCallWithReason(e) => {
84	                Error::FailedCallWithReason(e)
85	            }
86	        }
87	    }
88	}
89	
90	impl MethodError for Error {
91	    fn encode(self) -> alloc::vec::Vec<u8> {
92	        self.into()
93	    }
94	}
