127	/// This library provides getters and event emitting update functions for
128	/// [ERC-1967] slots.
129	///
130	/// [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
131	pub struct Erc1967Utils;
132	
133	/// Implementation of the [`Erc1967Utils`] library.
134	impl Erc1967Utils {
135	    /// Returns the current implementation address.
136	    #[must_use]
137	    pub fn get_implementation(context: &impl HostAccess<Host = VM>) -> Address {
138	        StorageSlot::get_slot::<StorageAddress>(context, IMPLEMENTATION_SLOT).get()
139	    }
140	
141	    /// Performs implementation upgrade with additional setup call if
142	    /// data is nonempty. This function is payable only if the setup call
143	    /// is performed, otherwise [`self.vm().msg_value()`] is rejected to avoid stuck
144	    /// value in the contract.
145	    ///
146	    /// # Arguments
147	    ///
148	    /// * `context` - Mutable access to the contract's state.
149	    /// * `new_implementation` - The new implementation address.
150	    /// * `data` - The data to pass to the setup call.
151	    ///
152	    /// # Errors
153	    ///
154	    /// * [`Error::InvalidImplementation`] - If the `new_implementation` address
155	    ///   is not a valid implementation.
156	    /// * [`Error::NonPayable`] - If `data` is empty and [`msg::value`] is not
157	    ///   [`U256::ZERO`].
158	    /// * [`Error::FailedCall`] - If the call to the implementation contract
159	    ///   fails.
160	    /// * [`Error::FailedCallWithReason`] - If the call to the implementation
161	    ///   contract fails with a revert reason.
162	    pub fn upgrade_to_and_call<T: TopLevelStorage + HostAccess<Host = VM>>(
163	        context: &mut T,
164	        new_implementation: Address,
165	        data: &Bytes,
166	    ) -> Result<(), Error> {
167	        Erc1967Utils::set_implementation(context, new_implementation)?;
168	
169	        context.vm().log(erc1967::Upgraded { implementation: new_implementation });
170	
171	        if data.is_empty() {
172	            Erc1967Utils::check_non_payable(context)?;
173	        } else {
174	            AddressUtils::function_delegate_call(
175	                context,
176	                new_implementation,
177	                data.as_ref(),
178	            )?;
179	        }
180	
181	        Ok(())
182	    }
183	
184	    /// Returns the current admin.
185	    #[must_use]
186	    pub fn get_admin(context: &impl HostAccess<Host = VM>) -> Address {
187	        StorageSlot::get_slot::<StorageAddress>(context, ADMIN_SLOT).get()
188	    }
189	
190	    /// Changes the admin of the proxy.
191	    ///
192	    /// # Arguments
193	    ///
194	    /// * `new_admin` - The new admin address.
195	    ///
196	    /// # Errors
197	    ///
198	    /// * [`Error::InvalidAdmin`] - If the `new_admin` address is not a valid
199	    ///   admin.
200	    pub fn change_admin(
201	        context: &impl HostAccess<Host = VM>,
202	        new_admin: Address,
203	    ) -> Result<(), Error> {
204	        context.vm().log(erc1967::AdminChanged {
205	            previous_admin: Erc1967Utils::get_admin(context),
206	            new_admin,
207	        });
208	
209	        Erc1967Utils::set_admin(context, new_admin)
210	    }
211	
212	    /// Returns the current beacon.
213	    #[must_use]
214	    pub fn get_beacon(context: &impl HostAccess<Host = VM>) -> Address {
215	        StorageSlot::get_slot::<StorageAddress>(context, BEACON_SLOT).get()
216	    }
217	
218	    /// Change the beacon and trigger a setup call if data is nonempty.
219	    /// This function is payable only if the setup call is performed,
220	    /// otherwise [`self.vm().msg_value()`] is rejected to avoid stuck value in the
221	    /// contract.
222	    ///
223	    /// # Arguments
224	    ///
225	    /// * `context` - Mutable access to the contract's state.
226	    /// * `new_beacon` - The new beacon address.
227	    /// * `data` - The data to pass to the setup call.
228	    ///
229	    /// # Errors
230	    ///
231	    /// * [`Error::InvalidBeacon`] - If the `new_beacon` address is not a valid
232	    ///   beacon.
233	    /// * [`Error::InvalidImplementation`] - If the beacon implementation is not
234	    ///   a valid implementation.
235	    /// * [`Error::NonPayable`] - If `data` is empty and [`msg::value`] is not
236	    ///   [`U256::ZERO`].
237	    /// * [`Error::FailedCall`] - If the call to the beacon implementation
238	    ///   fails.
239	    /// * [`Error::FailedCallWithReason`] - If the call to the beacon
240	    ///   implementation fails with a revert reason.
241	    pub fn upgrade_beacon_to_and_call<T: TopLevelStorage + HostAccess<Host = VM>>(
242	        context: &mut T,
243	        new_beacon: Address,
244	        data: &Bytes,
245	    ) -> Result<(), Error> {
246	        Erc1967Utils::set_beacon(context, new_beacon)?;
247	        context.vm().log(erc1967::BeaconUpgraded { beacon: new_beacon });
248	
249	        if data.is_empty() {
250	            Erc1967Utils::check_non_payable(context)?;
251	        } else {
252	            let beacon_implementation =
253	                Erc1967Utils::get_beacon_implementation(context, new_beacon)?;
254	
255	            AddressUtils::function_delegate_call(
256	                context,
257	                beacon_implementation,
258	                data.as_ref(),
259	            )?;
260	        }
261	
262	        Ok(())
263	    }
264	}
