266	impl Erc1967Utils {
267	    /// Reverts if [`self.vm().msg_value()`] is not [`alloy_primitives::U256::ZERO`]. It
268	    /// can be used to avoid [`self.vm().msg_value()`] stuck in the contract if an
269	    /// upgrade does not perform an initialization call.
270	    ///
271	    /// # Errors
272	    ///
273	    /// * [`Error::NonPayable`] - If [`self.vm().msg_value()`] is not
274	    ///   [`alloy_primitives::U256::ZERO`].
275	    fn check_non_payable(context: &impl HostAccess<Host = VM>) -> Result<(), Error> {
276	        if context.vm().msg_value().is_zero() {
277	            Ok(())
278	        } else {
279	            Err(ERC1967NonPayable {}.into())
280	        }
281	    }
282	
283	    /// Stores a new address in the ERC-1967 implementation slot.
284	    ///
285	    /// # Arguments
286	    ///
287	    /// * `new_implementation` - The new implementation address.
288	    ///
289	    /// # Errors
290	    ///
291	    /// * [`Error::InvalidImplementation`] - If the `new_implementation` address
292	    ///   is not a valid implementation.
293	    fn set_implementation(
294	        context: &impl HostAccess<Host = VM>,
295	        new_implementation: Address,
296	    ) -> Result<(), Error> {
297	        if !AddressUtils::has_code(context, new_implementation) {
298	            return Err(ERC1967InvalidImplementation {
299	                implementation: new_implementation}
300	            .into());
301	        }
302	
303	        StorageSlot::get_slot::<StorageAddress>(context, IMPLEMENTATION_SLOT)
304	            .set(new_implementation);
305	
306	        Ok(())
307	    }
308	
309	    /// Stores a new address in the ERC-1967 admin slot.
310	    ///
311	    /// # Arguments
312	    ///
313	    /// * `new_admin` - The new admin address.
314	    ///
315	    /// # Errors
316	    ///
317	    /// * [`Error::InvalidAdmin`] - If the `new_admin` address is not a valid
318	    ///   admin.
319	    fn set_admin(
320	        context: &impl HostAccess<Host = VM>,
321	        new_admin: Address,
322	    ) -> Result<(), Error> {
323	        if new_admin.is_zero() {
324	            return Err(ERC1967InvalidAdmin { admin: new_admin }.into());
325	        }
326	
327	        StorageSlot::get_slot::<StorageAddress>(context, ADMIN_SLOT).set(new_admin);
328	
329	        Ok(())
330	    }
331	
332	    /// Stores a new beacon in the ERC-1967 beacon slot.
333	    ///
334	    /// # Arguments
335	    ///
336	    /// * `context` - Mutable access to the contract's state.
337	    /// * `new_beacon` - The new beacon address.
338	    ///
339	    /// # Errors
340	    ///
341	    /// * [`Error::InvalidBeacon`] - If the `new_beacon` address is not a valid
342	    ///   beacon.
343	    /// * [`Error::InvalidImplementation`] - If the beacon implementation is not
344	    ///   a valid implementation.
345	    /// * [`Error::FailedCall`] - If the call to the beacon implementation
346	    ///   fails.
347	    /// * [`Error::FailedCallWithReason`] - If the call to the beacon
348	    ///   implementation fails with a revert reason.
349	    fn set_beacon<T: TopLevelStorage + HostAccess<Host = VM>>(
350	        context: &mut T,
351	        new_beacon: Address,
352	    ) -> Result<(), Error> {
353	        if !AddressUtils::has_code(context, new_beacon) {
354	            return Err(ERC1967InvalidBeacon { beacon: new_beacon }.into());
355	        }
356	
357	        StorageSlot::get_slot::<StorageAddress>(context, BEACON_SLOT).set(new_beacon);
358	
359	        let beacon_implementation =
360	            Erc1967Utils::get_beacon_implementation(context, new_beacon)?;
361	
362	        if !AddressUtils::has_code(context, beacon_implementation) {
363	            return Err(ERC1967InvalidImplementation {
364	                implementation: beacon_implementation}
365	            .into());
366	        }
367	
368	        Ok(())
369	    }
370	}
