372	impl Erc1967Utils {
373	    /// Returns the implementation address of the beacon.
374	    ///
375	    /// # Arguments
376	    ///
377	    /// * `context` - Readonly access to the contract's state.
378	    /// * `beacon` - The beacon address.
379	    ///
380	    /// # Errors
381	    ///
382	    /// * [`Error::FailedCall`] - If the call to the beacon implementation
383	    ///   fails.
384	    /// * [`Error::FailedCallWithReason`] - If the call to the beacon
385	    ///   implementation fails with a revert reason.
386	    /// * [`Error::EmptyCode`] - If the beacon implementation has no code.
387	    fn get_beacon_implementation<T: TopLevelStorage + HostAccess<Host = VM>>(
388	        context: &T,
389	        beacon: Address,
390	    ) -> Result<Address, Error> {
391	        Ok(AddressUtils::verify_call_result_from_target(
392	            context,
393	            beacon,
394	            IBeaconInterface::new(beacon).implementation(context.vm(), Call::new()),
395	        )?)
396	    }
397	}
