1	//! Universal Upgradeable Proxy Standard (UUPS) as defined in
2	//! [ERC-1822]: <https://eips.ethereum.org/EIPS/eip-1822>.
3	
4	use alloc::vec::Vec;
5	use stylus_sdk::prelude::public;
6	
7	use alloy_primitives::aliases::B256;
8	use openzeppelin_stylus_proc::interface_id;
9	
10	/// Public interface for Universal Upgradeable Proxy Standard (UUPS).
11	///
12	/// This interface documents a method for upgradeability through a simplified
13	/// proxy whose upgrades are fully controlled by the current implementation.
14	#[interface_id]
15	#[public]
16	pub trait IErc1822Proxiable {
17	    /// Returns the storage slot that the proxiable contract assumes is being
18	    /// used to store the implementation address.
19	    ///
20	    /// # Arguments
21	    ///
22	    /// * `&self` - Read access to the contract's state.
23	    ///
24	    /// # Errors
25	    ///
26	    /// * May return an error based on the implementation.
27	    #[selector(name = "proxiableUUID")]
28	    fn proxiable_uuid(&self) -> Result<B256, Vec<u8>>;
29	}
30	
31	pub use erc1822_sol::Erc1822ProxiableInterface;
32	
33	mod erc1822_sol {
34	    //! Solidity Interface of the ERC-1822 proxiable.
35	
36	    #![allow(missing_docs)]
37	    #![cfg_attr(coverage_nightly, coverage(off))]
38	
39	    use alloc::vec;
40	
41	    use stylus_sdk::prelude::sol_interface;
42	
43	    sol_interface! {
44	        interface Erc1822ProxiableInterface {
45	            function proxiableUUID() external view returns (bytes32);
46	        }
47	    }
48	}
