//! Common imports for Stylus contracts.
//!
//! Included are all the proc macros and common traits.
//!
//! ```
//! use stylus_sdk::prelude::*;
//! ```

pub use crate::{
    call::*,
    storage::{Erase, SimpleStorageType, StorageType},
    stylus_core::*,
    stylus_proc::*,
