//! Defines a builder struct that can create a [`crate::TestVM`] instance
//! with convenient overrides for unit testing Stylus contracts.

use std::{collections::HashMap, sync::Arc};

use alloy_primitives::{Address, B256, U256};
use alloy_provider::{network::Ethereum, RootProvider};
use url::Url;

use crate::{state::VMState, TestVM};

/// Builder for constructing a [`crate::TestVM`] used for unit testing Stylus contracts built with
/// the Stylus SDK. Allows for convenient customization of the contract's address, sender address,
/// message value, and RPC URL if state forking is desired. These values and more can still be
/// customized if the builder is not used, by instead invoking the corresponding method on the
/// TestVM struct such as `vm.set_value(value)`.
///
/// # Example
/// ```
/// use alloy_primitives::{address, Address, U256};
/// use stylus_test::{TestVM, TestVMBuilder};
///
/// let vm: TestVM = TestVMBuilder::new()
///     .sender(address!("dCE82b5f92C98F27F116F70491a487EFFDb6a2a9"))
///     .contract_address(address!("DeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF"))
///     .value(U256::from(1))
///     .rpc_url("http://localhost:8547")
///     .build();
/// ```
#[derive(Default)]
pub struct TestVMBuilder {
    sender: Option<Address>,
    value: Option<U256>,
    contract_address: Option<Address>,
    rpc_url: Option<String>,
    storage: Option<HashMap<U256, B256>>,
    provider: Option<Arc<RootProvider<Ethereum>>>,
    block_num: Option<u64>,
    chain_id: Option<u64>,
}

impl TestVMBuilder {
    pub fn new() -> Self {
        Self::default()
    }
    /// Sets the sender address for contract invocations.
    pub fn sender(mut self, sender: Address) -> Self {
        self.sender = Some(sender);
        self
    }
    /// Sets the block number.
    pub fn block_number(mut self, block_num: u64) -> Self {
        self.block_num = Some(block_num);
        self
    }
    /// Sets the chain id.
    pub fn chain_id(mut self, id: u64) -> Self {
        self.chain_id = Some(id);
        self
    }
    /// Sets the storage mapping.
    pub fn storage(mut self, mapping: HashMap<U256, B256>) -> Self {
        self.storage = Some(mapping);
        self
    }
    /// Sets the msg value for contract invocations.
    pub fn value(mut self, value: U256) -> Self {
        self.value = Some(value);
        self
    }
    /// Sets the contract address.
    pub fn contract_address(mut self, address: Address) -> Self {
        self.contract_address = Some(address);
        self
    }
    /// Sets the RPC URL to a Stylus-enabled Arbitrum chain for storage forking.
    /// If specified, any calls to load storage will be made to the RPC URL at the TestVM's
    /// specified contract address.
    pub fn rpc_url(mut self, url: &str) -> Self {
        let url = match Url::parse(url) {
            Ok(url) => url,
            Err(e) => {
                panic!("Invalid RPC URL specified: {e}");
            }
        };
        self.rpc_url = Some(url.to_string());
        self.provider = Some(Arc::new(RootProvider::new_http(url)));
        self
    }
    /// Returns and TestVM instance from the builder with the specified parameters.
    pub fn build(self) -> TestVM {
        let mut state = VMState::default();
        if let Some(sender) = self.sender {
            state.msg_sender = sender;
        }
        if let Some(value) = self.value {
            state.msg_value = value;
        }
        if let Some(storage) = self.storage {
            state.storage = storage;
        }
        if let Some(block_number) = self.block_num {
            state.block_number = block_number;
        }
        if let Some(id) = self.chain_id {
            state.chain_id = id;
        }
        if let Some(contract_address) = self.contract_address {
            state.contract_address = contract_address;
        }
        state.provider = self.provider;
        TestVM::from(state)
    }
}

    /// let value = vm.get_storage(key);
    /// assert_eq!(value, B256::ZERO);
    /// ```
    pub fn get_storage(&self, key: U256) -> B256 {
        self.state
            .borrow()
            .storage
            .get(&key)
            .copied()
            .unwrap_or_default()
    }

    /// Sets a storage value.
    pub fn set_storage(&self, key: U256, value: B256) {
        self.state.borrow_mut().storage.insert(key, value);
    }

    /// Clears all storage.
    pub fn clear_storage(&self) {
        self.state.borrow_mut().storage.clear();
    }

    /// Mocks a contract call.
    ///
    /// # Examples
    /// ```
    /// # use stylus_test::TestVM;
    /// # use alloy_primitives::{Address, U256};
    /// let vm = TestVM::new();
    /// let contract = Address::from([1u8; 20]);
    /// let data = vec![0x01, 0x02, 0x03];
    ///
    /// // Mock successful call
    /// let value = U256::from(1);
    /// vm.mock_call(contract, data.clone(), value, Ok(vec![0x04]));
    ///
    /// let value = U256::from(0);
    /// // Mock reverted call
    /// vm.mock_call(contract, data, value, Err(vec![0xff]));
    /// ```
    pub fn mock_call(
        &self,
        to: Address,
        data: Vec<u8>,
        value: U256,
        return_data: Result<Vec<u8>, Vec<u8>>,
    ) {
        let mut state = self.state.borrow_mut();
        state.return_data = match return_data.clone() {
            Ok(data) => data,
            Err(data) => data,
        };
        state.call_returns.insert((to, data, value), return_data);
    }

    /// Mocks a delegate call.
    pub fn mock_delegate_call(
        &self,
        to: Address,
        data: Vec<u8>,
        return_data: Result<Vec<u8>, Vec<u8>>,
    ) {
        let mut state = self.state.borrow_mut();
        state.return_data = match return_data.clone() {
            Ok(data) => data,
            Err(data) => data,
        };

        state.delegate_call_returns.insert((to, data), return_data);
    }

    /// Mocks a static call.
    pub fn mock_static_call(
        &self,
        to: Address,
        data: Vec<u8>,
        return_data: Result<Vec<u8>, Vec<u8>>,
    ) {
        let mut state = self.state.borrow_mut();
        state.return_data = match return_data.clone() {
            Ok(data) => data,
            Err(data) => data,
        };
        state.static_call_returns.insert((to, data), return_data);
    }

    /// Mocks contract deployment.
    ///
    /// # Examples
    /// ```
    /// # use stylus_test::TestVM;
    /// # use alloy_primitives::{Address, B256};
    /// let vm = TestVM::new();
    /// let code = vec![0x60, 0x80, 0x60, 0x40];
    /// let salt = Some(B256::with_last_byte(1));
    /// let deployed_address = Address::from([2u8; 20]);
    ///
    /// vm.mock_deploy(code, salt, Ok(deployed_address));
    /// ```
    pub fn mock_deploy(&self, code: Vec<u8>, salt: Option<B256>, result: Result<Address, Vec<u8>>) {
        self.state
            .borrow_mut()
            .deploy_returns
            .insert((code, salt), result);
    }

    /// Gets all emitted logs.
    pub fn get_emitted_logs(&self) -> Vec<(Vec<B256>, Vec<u8>)> {
        self.state.borrow().emitted_logs.clone()
    }

    /// Clears all mocks and logs.
    pub fn clear_mocks(&self) {
        let mut state = self.state.borrow_mut();
        state.call_returns.clear();
        state.delegate_call_returns.clear();
        state.static_call_returns.clear();
        state.deploy_returns.clear();
        state.emitted_logs.clear();
        state.return_data.clear();
    }

    fn perform_mocked_call(
        &self,
        to: Address,
        data: Vec<u8>,
        value: U256,
    ) -> Result<Vec<u8>, Vec<u8>> {
        let state = self.state.borrow();
        if let Some(return_data) = state.call_returns.get(&(to, data.clone(), value)) {
            return return_data.clone();
        }
        Ok(Vec::new())
    }

    /// Performs a mocked call to a contract.
    fn perform_mocked_delegate_call(&self, to: Address, data: Vec<u8>) -> Result<Vec<u8>, Vec<u8>> {
        let state = self.state.borrow();
        if let Some(return_data) = state.delegate_call_returns.get(&(to, data.clone())) {
            return return_data.clone();
        }
        Ok(Vec::new())
    }

    /// Performs a mocked call to a contract.
    fn perform_mocked_static_call(&self, to: Address, data: Vec<u8>) -> Result<Vec<u8>, Vec<u8>> {
        let state = self.state.borrow();
        if let Some(return_data) = state.static_call_returns.get(&(to, data.clone())) {
            return return_data.clone();
        }
        Ok(Vec::new())
    }
}

