    ///   the owner.
    pub fn only_owner(&self) -> Result<(), Error> {
        let account = self.vm().msg_sender();
        if self.owner() != account {
            return Err(Error::UnauthorizedAccount(
                OwnableUnauthorizedAccount { account },
            ));
        }

        Ok(())
    }

